  "ui.wpAdminAgentFrameApp.feedback100": "Brak dostępnego lokalnego CLI. Otwórz Ustawienia → Wykonywanie i połącz OpenCode lub inne obsługiwane środowisko.",
  "ui.wpAdminAgentFrameApp.feedback101": "Wybierz dostępnego agenta w Ustawienia → Wykonywanie.",
  "ui.wpAdminAgentFrameApp.feedback102": "Dołącz ponownie {value1}, aby można było znaleźć obszar przesyłania.",
  "ui.wpAdminAgentFrameApp.feedback103": "Bieżący kontekst administratora WordPressa nie uprawnia do odczytu wybranego celu {value1}. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback104": "Nie udało się ponownie potwierdzić uprawnień do wyraźnie wybranego wpisu WordPressa {value1}. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback105": "Nie udało się w pełni wczytać bieżącego dokumentu Gutenberga ({value1}). Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback106": "Bieżący dokument Gutenberga jest dostępny tylko jako powiązana migawka w częściach. Edycja całego dokumentu wymaga odczytania wszystkich potrzebnych części. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback107": "Bieżący wpis Gutenberga ma niezapisane zmiany. Zapisz lub zaktualizuj go, zanim Pixflow odczyta go lub przygotuje edycję uwzględniającą treść. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback108": "Usunięcie wszystkich bloków Gutenberga nie jest obecnie obsługiwane. Pixflow nie zinterpretował żądania jako zastąpienia pustą treścią i niczego nie zmienił.",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow nie rozpoznał, czy wiadomość odpowiada na oczekujące doprecyzowanie, czy rozpoczyna nowe żądanie. Nie przygotowano przeglądu i niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback110": "Bieżący dokument Gutenberga jest podzielony na części i nie został w pełni odczytany, więc Pixflow nie może przygotować przeglądu całego dokumentu. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback111": "Nie zażądano wyraźnie pełnego zastąpienia Gutenberga, więc Pixflow odmówił zastąpienia bieżącego dokumentu. Niczego nie zmieniono.",
  "ui.wpAdminAgentFrameApp.feedback112": "Pixflow nie mógł odświeżyć uprawnień obiektu WordPressa po poprzednim działaniu. Wcześniejsze działania zostaną cofnięte.",
  "ui.wpAdminAgentFrameApp.feedback113": "Wymagany wpis nie został utworzony z prawidłowym identyfikatorem WordPressa. Wcześniejsze działania zostaną cofnięte.",
  "ui.wpAdminAgentFrameApp.feedback114": "Pixflow nie mógł potwierdzić aktualnych uprawnień do nowego wpisu. Wcześniejsze działania zostaną cofnięte.",
  "ui.wpAdminAgentFrameApp.feedback115": "Nowy wpis nie jest edytowalnym celem edytora blokowego. Wcześniejsze działania zostaną cofnięte.",
  "ui.savedMemorySettings.delete": "Usunąć „{name}”?",
