  "wp.message.26a6374fbf59": "Nie udało się uruchomić dodatku Pixflow. Sprawdź zgodność wtyczek Pixflow i odśwież stronę. Pozostałe funkcje mogą nadal być dostępne.",
  "wp.message.ca7714cffbcc": "Aktywuj Pro",
  "wp.message.197c83a2f752": "Przywróć narzędzia premium dzięki dodatkowi Pro. Licencja, treści i zapisane ustawienia pozostaną zachowane. Jeśli używano uwierzytelniania dwuskładnikowego Bricks, włącz je ponownie w ustawieniach po aktywacji Pro.",
