  "ui.finalOnboarding.f54f5d4bcd": "Twoja konfiguracja",
  "ui.finalOnboarding.7d2d594053": "Jak chcesz korzystać z Pixflow?",
  "ui.finalOnboarding.bdf73477f9": "Połącz dostawcę API",
  "ui.finalOnboarding.28edc3b8f2": "Połącz swoją subskrypcję AI",
  "ui.finalOnboarding.f9573d1164": "Możesz zacząć tworzyć",
  "ui.finalOnboarding.45ddd1221b": "Edycja WordPress i Gutenberg jest bezpłatna. Nie wymaga licencji ani okresu próbnego.",
  "ui.finalOnboarding.6072f06060": "Aktywuj licencję, aby rozpocząć. Jest już aktywna? Pojawi się tutaj.",
  "ui.finalOnboarding.ae83bc42b4": "Wybierz odpowiednią opcję. Możesz ją zmienić w Ustawieniach w dowolnym momencie.",
  "ui.finalOnboarding.c9e2eb7fcb": "Użyj klucza API swojego dostawcy. Ta metoda nie wymaga Bridge.",
  "ui.finalOnboarding.5add76d77c": "Bridge łączy tę witrynę z agentami AI na Twoim komputerze. Dostęp do AI zapewnia konto u dostawcy.",
  "ui.finalOnboarding.4813d31d25": "Korzystaj z obszaru roboczego WordPress bez łączenia AI.",
  "ui.finalOnboarding.fbcd710247": "Połączenie jest skonfigurowane. Zadaj pytanie lub opisz, co chcesz zbudować.",
  "ui.finalOnboarding.24fba6f166": "Połącz subskrypcję AI",
  "ui.finalOnboarding.82d6b8daef": "Korzystaj z obsługiwanych agentów, takich jak Codex lub OpenCode, przez Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "Użyj klucza API",
  "ui.finalOnboarding.e76c3bfd0e": "Połącz się bezpośrednio ze swoim dostawcą. Użycie API jest rozliczane osobno.",
  "ui.finalOnboarding.1be451ef72": "Kontynuuj bez AI",
  "ui.finalOnboarding.88e6e83b86": "Korzystaj z obszaru roboczego WordPress. AI możesz dodać później.",
  "ui.finalOnboarding.105e56e56f": "Dlaczego wybrać lokalny CLI?",
  "ui.finalOnboarding.5df057fcd7": "Użycie API jest rozliczane osobno",
  "ui.finalOnboarding.44e30ed15f": "BYOK wymaga klucza API. Dostawca AI rozlicza użycie API oddzielnie od subskrypcji CLI, więc może to oznaczać dodatkowe koszty zamiast wykorzystania dołączonych lub tygodniowych limitów konta CLI.",
  "ui.finalOnboarding.5f9b0ae108": "Tylko sesja",
  "ui.finalOnboarding.3c0e1f05da": "Zachowuj kontekst tylko podczas otwartej sesji panelu. Przeładowanie rozpoczyna od nowa.",
