  "ui.finalOnboarding.a7f9620cca": "Na tym urządzeniu",
  "ui.finalOnboarding.94536fb7d6": "Zachowuj ograniczony kontekst lokalny między ponownymi uruchomieniami przeglądarki na tym urządzeniu.",
